   auto vn=read.operator()<std::uint16_t>();if(vn>count)throw std::runtime_error("value count");bad|=vn!=count-dead.size();for(unsigned i=0;i<vn;++i){auto id=read.operator()<std::uint32_t>(),bits=read.operator()<std::uint32_t>();auto cache=read.operator()<std::uint64_t>();if(id<100||id>=100+count)throw std::runtime_error("value id");if(dead.contains(id))bad=true;else bad|=all[id-100]->value().tag()!=1||all[id-100]->value().scalar_bits()!=bits||all[id-100]->cached_bits()!=cache;}
